-- Faithful Shop.dat -> system_shop port (2026-06-29)
-- Mirrors the client Shop.dat catalog (real PB period codes + prices) so the
-- server builds GoodsItem.Id = itemId*100 + period_code == the client's GoodsID.
-- Pairs with the ShopManager variant_code_list change.
BEGIN;

DROP TABLE IF EXISTS _bak_system_shop_faithport_20260629;
CREATE TABLE _bak_system_shop_faithport_20260629 AS SELECT * FROM system_shop;

ALTER TABLE system_shop ADD COLUMN IF NOT EXISTS variant_code_list varchar NOT NULL DEFAULT '';

CREATE TEMP TABLE _shopcat(item_id int PRIMARY KEY, codes text, counts text, cash text, gold text, visible int) ON COMMIT DROP;

-- update existing items in place (keeps item_name/consume/tag/etc.)
UPDATE system_shop s SET
  variant_code_list = c.codes,
  "Item_count_list" = c.counts,
  price_cash_list   = c.cash,
  price_gold_list   = c.gold,
  item_visible      = (c.visible = 1)
FROM _shopcat c WHERE s.item_id = c.item_id;

-- insert Shop.dat items missing from system_shop (defaults for the non-price columns)
SELECT c.item_id, '', 2, c.counts, c.cash, c.gold, 0, 0, (c.visible=1), 0, 0, 0, 0, 2, c.codes
FROM _shopcat c WHERE NOT EXISTS (SELECT 1 FROM system_shop s WHERE s.item_id = c.item_id);

UPDATE system_shop
SET item_consume = 2
WHERE item_id / 100000 = 15
  AND item_consume = 1
  AND "Item_count_list" ~ '(^|,)86400(,|$)';

WITH period_seconds(code, seconds) AS (
    VALUES
        ('02', 7200), ('03', 604800), ('04', 86400), ('05', 172800),
        ('06', 259200), ('07', 432000), ('08', 604800), ('09', 864000),
        ('11', 1296000), ('12', 2592000), ('15', 345600), ('20', 2592000),
        ('21', 2678400), ('23', 3024000), ('24', 3456000), ('26', 5184000),
        ('27', 7776000), ('28', 10368000), ('34', 315360000)
)
UPDATE system_shop AS s
SET "Item_count_list" = (
    SELECT string_agg(
        CASE
            WHEN trim(c.val) = '1' THEN COALESCE(p.seconds::text, trim(c.val))
            ELSE trim(c.val)
        END,
        ',' ORDER BY c.ord
    )
    FROM unnest(string_to_array(s."Item_count_list", ',')) WITH ORDINALITY AS c(val, ord)
    JOIN unnest(string_to_array(s.variant_code_list, ',')) WITH ORDINALITY AS v(code, code_ord)
      ON c.ord = v.code_ord
    LEFT JOIN period_seconds AS p ON trim(v.code) = p.code
)
WHERE s.item_id / 100000 = 16 AND s.item_consume = 2 AND s.variant_code_list <> '';

SELECT 'system_shop_total' AS k, count(*)::text AS v FROM system_shop
UNION ALL SELECT 'with_variant_codes', count(*)::text FROM system_shop WHERE variant_code_list <> ''
UNION ALL SELECT 'catalog_items', count(*)::text FROM _shopcat;

COMMIT;
